$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Synthetic navigation');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','member',1),('member','a','member',0),('reader','a','member',0),('editor','a','editor',0),('disabled','a','members',0)");
