$db->exec("INSERT INTO actors(id,club_id,role) VALUES('settings-manager','a','members')");$managerAccess=new WorkspaceAccess($db,'settings-manager');check($managerAccess->allows(['view'=>'settings']),'ordinary settings manager keeps club settings');check(!$managerAccess->allows(['view'=>'settings','section'=>'mail']),'ordinary settings manager cannot enter mailbox settings');check((new WorkspaceAccess($db,'admin'))->allows(['view'=>'settings','section'=>'mail']),'superuser mailbox destination allowed');foreach(ManagerNavigation::search($managerAccess) as $entry)check(!(($entry['route']['view']??'')==='settings'&&($entry['route']['section']??'')==='mail'),'mailbox destination absent from ordinary manager search');
foreach(['admin','member','reader','editor','disabled'] as $actor){$access=new WorkspaceAccess($db,$actor);$groups=ManagerNavigation::groups($access);$ids=[];foreach($groups as $group){check((bool)$group['items'],$actor.' has no empty group '.$group['id']);foreach($group['items'] as $item){check($access->allows($item['route']),$actor.' main target authorized '.$item['id']);$ids[]=$item['id'];}}check(count($ids)===count(array_unique($ids)),$actor.' unique item ids');$search=ManagerNavigation::search($access);$targets=[];foreach($search as $entry){check($access->allows($entry['route']),$actor.' search target authorized '.$entry['label']);$route=$entry['route'];ksort($route);$targets[]=http_build_query($route);}check(count($targets)===count(array_unique($targets)),$actor.' no duplicate search destinations');if($actor==='disabled')check($groups===[]&&$search===[],'disabled account sees neither menu nor search');if($actor==='editor'){foreach($groups as $group)check(in_array($group['id'],['start','website','communication','settings'],true),'editor internal group hidden '.$group['id']);foreach($search as $entry)check(in_array($entry['route']['view'],['dashboard','website','social','newsletter','press','settings'],true)&&(($entry['route']['view']!=='settings')||in_array($entry['route']['tab']??'',['api','languages'],true)),'editor search stays in permitted boundary');}}
$editorAccess=new WorkspaceAccess($db,'editor');foreach([['view'=>'finance','tab'=>'bank'],['view'=>'finance','tab'=>'tax'],['view'=>'settings','tab'=>'roles'],['view'=>'settings','section'=>'mail'],['view'=>'settings','tab'=>'account']]as$route)check(!$editorAccess->allows($route),'editor keeps independent boundary '.http_build_query($route));
$groups=ManagerNavigation::groups(new WorkspaceAccess($db,'reader'));$inventory=null;foreach($groups as $group)foreach($group['items'] as $item)if($item['id']==='organisation:inventory')$inventory=$item;check($inventory===null,'finance-only reader does not get an inventory fallback');check(ManagerNavigation::key(['view'=>'inventory','tab'=>'assets'])==='finance:reports','finance reader assets belong to finance reports');
check(ManagerNavigation::key(['view'=>'portal','tab'=>'own'])==='portal:own','own profile active');check(ManagerNavigation::key(['view'=>'portal','tab'=>'documents'])==='portal:own','own documents active');
